import{_ as e,r as s,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Отправка почты - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, как отправлять почту и создавать шаблоны.","frontmatter":{"subtitle":"Узнайте, как отправлять почту и создавать шаблоны."},"headers":[{"level":2,"title":"Содержимое сообщения","slug":"содержимое-сообщения","link":"#содержимое-сообщения","children":[{"level":3,"title":"Определение шаблонов в панели управления","slug":"определение-шаблонов-в-панели-управления","link":"#определение-шаблонов-в-панели-управления","children":[]},{"level":3,"title":"Определение макетов в панели управления","slug":"определение-макетов-в-панели-управления","link":"#определение-макетов-в-панели-управления","children":[]},{"level":3,"title":"Определение представлений в файловой системе","slug":"определение-представлении-в-фаиловои-системе","link":"#определение-представлении-в-фаиловои-системе","children":[{"level":4,"title":"Секция конфигурации","slug":"секция-конфигурации","link":"#секция-конфигурации","children":[]}]},{"level":3,"title":"Регистрация шаблонов, макетов и частичных представлений","slug":"регистрация-шаблонов-макетов-и-частичных-представлении","link":"#регистрация-шаблонов-макетов-и-частичных-представлении","children":[{"level":4,"title":"Регистрация шаблона","slug":"регистрация-шаблона","link":"#регистрация-шаблона","children":[]},{"level":4,"title":"Регистрация макета","slug":"регистрация-макета","link":"#регистрация-макета","children":[]},{"level":4,"title":"Регистрация частичного представления","slug":"регистрация-частичного-представления","link":"#регистрация-частичного-представления","children":[]},{"level":4,"title":"Файловые макеты","slug":"фаиловые-макеты","link":"#фаиловые-макеты","children":[]}]},{"level":3,"title":"Глобальные переменные","slug":"глобальные-переменные","link":"#глобальные-переменные","children":[]}]},{"level":2,"title":"Отправка почты","slug":"отправка-почты","link":"#отправка-почты","children":[{"level":3,"title":"Быстрая отправка","slug":"быстрая-отправка","link":"#быстрая-отправка","children":[]},{"level":3,"title":"Построение сообщения","slug":"построение-сообщения","link":"#построение-сообщения","children":[{"level":4,"title":"Отправка простого текста","slug":"отправка-простого-текста","link":"#отправка-простого-текста","children":[]},{"level":4,"title":"Отправка обработанных сырых строк","slug":"отправка-обработанных-сырых-строк","link":"#отправка-обработанных-сырых-строк","children":[]},{"level":4,"title":"Отправка сырых строк","slug":"отправка-сырых-строк","link":"#отправка-сырых-строк","children":[]}]},{"level":3,"title":"Отправка вложений","slug":"отправка-вложении","link":"#отправка-вложении","children":[]},{"level":3,"title":"Встроенные вложения","slug":"встроенные-вложения","link":"#встроенные-вложения","children":[{"level":4,"title":"Встраивание изображения в содержимое письма","slug":"встраивание-изображения-в-содержимое-письма","link":"#встраивание-изображения-в-содержимое-письма","children":[]},{"level":4,"title":"Встраивание сырых данных в содержимое письма","slug":"встраивание-сырых-данных-в-содержимое-письма","link":"#встраивание-сырых-данных-в-содержимое-письма","children":[]}]}]},{"level":2,"title":"Очередь почты","slug":"очередь-почты","link":"#очередь-почты","children":[{"level":3,"title":"Постановка почтового сообщения в очередь","slug":"постановка-почтового-сообщения-в-очередь","link":"#постановка-почтового-сообщения-в-очередь","children":[]},{"level":3,"title":"Отложенная постановка в очередь","slug":"отложенная-постановка-в-очередь","link":"#отложенная-постановка-в-очередь","children":[]},{"level":3,"title":"Отправка в конкретные очереди","slug":"отправка-в-конкретные-очереди","link":"#отправка-в-конкретные-очереди","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}]}],"relativePath":"3.x/ru/extend/system/sending-mail.md","filePath":"3.x/ru/extend/system/sending-mail.md"}'),u={name:"3.x/ru/extend/system/sending-mail.md"};function r(k,n,d,g,m,h){const t=s("pre-heading"),p=s("post-heading");return o(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"Отправка почты",-1)),a(p),n[1]||(n[1]=i(`<p>В этой статье описывается, как создавать содержимое писем, включая использование макетов и частичных представлений, а затем методы, используемые для их отправки. В содержимом писем поддерживаются базовые Twig-теги и выражения. Также поддерживается синтаксис Markdown, подробнее см. раздел <a href="./../services/parser.html">использование HTML в Markdown</a>.</p><h2 id="содержимое-сообщения"><a href="#содержимое-сообщения" class="header-anchor">#</a> Содержимое сообщения</h2><p>Почтовые сообщения в October CMS могут быть отправлены с использованием либо почтовых представлений, либо почтовых шаблонов. Почтовое представление предоставляется приложением или плагином в файловой системе в директории <strong>/views</strong>. Почтовый шаблон же управляется через панель управления через <strong>Настройки → Шаблоны писем</strong>.</p><p>Опционально почтовые представления могут быть зарегистрированы в <a href="./../extending.html">файле регистрации плагина</a> с помощью метода <code>registerMailTemplates</code>. Это автоматически создаёт почтовый шаблон, позволяя настраивать его через панель управления.</p><h3 id="определение-шаблонов-в-панели-управления"><a href="#определение-шаблонов-в-панели-управления" class="header-anchor">#</a> Определение шаблонов в панели управления</h3><p>Вы можете создавать почтовые шаблоны, хранящиеся в базе данных, через панель управления <strong>Настройки → Шаблоны писем</strong>. <strong>Код</strong>, присвоенный шаблону, является уникальным идентификатором и не может быть изменён после создания.</p><p>Например, если вы создадите шаблон с кодом <code>my-template</code>, вы сможете отправить его с помощью следующего PHP-кода:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my-template&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Если почтовый шаблон не существует в системе, этот код попытается найти почтовое представление в файловой системе с тем же кодом.</p></div><h3 id="определение-макетов-в-панели-управления"><a href="#определение-макетов-в-панели-управления" class="header-anchor">#</a> Определение макетов в панели управления</h3><p>Почтовые макеты можно создать, выбрав <strong>Настройки → Шаблоны писем</strong> и нажав на вкладку <strong>Макеты</strong>. Они работают так же, как CMS-макеты — содержат каркас почтового сообщения. Почтовые представления и шаблоны поддерживают использование почтовых макетов.</p><p>По умолчанию October CMS поставляется с двумя стандартными почтовыми макетами.</p><div class="table"><table tabindex="0"><thead><tr><th>Макет</th><th>Код</th><th>Описание</th></tr></thead><tbody><tr><td>Default</td><td><code>default</code></td><td>Используется для публичной, фронтенд-почты.</td></tr><tr><td>System</td><td><code>system</code></td><td>Используется для внутренней почты панели управления.</td></tr></tbody></table></div><h3 id="определение-представлении-в-фаиловои-системе"><a href="#определение-представлении-в-фаиловои-системе" class="header-anchor">#</a> Определение представлений в файловой системе</h3><p>Почтовые представления находятся в файловой системе, и используемый код представляет путь к файлу представления. Например, отправка почты с кодом <code>author.plugin::mail.message</code> использует содержимое следующего файла.</p><pre class="dir-container"><code><p>├── plugins
|   └── author  <em>← Сегмент &quot;author&quot;</em>
|       └── myplugin  <em>← Сегмент &quot;plugin&quot;</em>
|           └── <code>views</code>
|               └── mail  <em>← Сегмент &quot;mail&quot;</em>
|                   └── message.htm  <em>← Сегмент &quot;message&quot;</em></p>
</code></pre><p>Содержимое файла почтового представления может включать до 3 секций: <strong>конфигурация</strong>, <strong>простой текст</strong> и <strong>HTML-разметка</strong>. Секции разделяются последовательностью <code>==</code>. Например:</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">subject</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Your product has been added to October CMS project</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code>Hi <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>,

Good news! User <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user <span class="token delimiter punctuation">}}</span></span> just added your product &quot;<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> product <span class="token delimiter punctuation">}}</span></span>&quot; to a project.

This message was sent using no formatting (plain text)
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Hi <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>,<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>strong</span><span class="token punctuation">&gt;</span></span>Good news!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>strong</span><span class="token punctuation">&gt;</span></span>
    User <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user <span class="token delimiter punctuation">}}</span></span> just added your product &quot;<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> product <span class="token delimiter punctuation">}}</span></span>&quot; to a project.
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>This email was sent using formatting (HTML)<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Секция <strong>простого текста</strong> является необязательной, и представление может содержать только секции <strong>конфигурации</strong> и <strong>HTML-разметки</strong>. Синтаксис Markdown также поддерживается как альтернативный синтаксис.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>
<span class="token key attr-name">subject</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Your product has been added to October CMS project</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code>Hi <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>,

**Good news!** User <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user <span class="token delimiter punctuation">}}</span></span> just added your product &quot;<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> product <span class="token delimiter punctuation">}}</span></span>&quot; to a project.
</code></pre></div></div><h4 id="секция-конфигурации"><a href="#секция-конфигурации" class="header-anchor">#</a> Секция конфигурации</h4><p>Секция конфигурации задаёт свойства почтового представления. Поддерживаются следующие свойства конфигурации.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>subject</strong></td><td>тема почтового сообщения, обязательно.</td></tr><tr><td><strong>layout</strong></td><td>код или представление почтового макета, необязательно. Значение по умолчанию — <code>default</code>.</td></tr></tbody></table></div><h3 id="регистрация-шаблонов-макетов-и-частичных-представлении"><a href="#регистрация-шаблонов-макетов-и-частичных-представлении" class="header-anchor">#</a> Регистрация шаблонов, макетов и частичных представлений</h3><div class="custom-block aside"><p>Значение <strong>code</strong> в панели управления будет таким же, как путь к почтовому представлению. Например, <code>author.plugin:mail.message</code>.</p></div><p>Почтовые представления могут быть зарегистрированы как шаблоны по умолчанию, создаваемые в панели управления. Шаблоны регистрируются путём переопределения метода <code>registerMailTemplates</code> <a href="./../extending.html">файла регистрации плагина</a>. Шаблоны могут реализовывать частичные представления и макеты, аналогично CMS-темам, и они регистрируются с помощью <code>registerMailLayouts</code> и <code>registerMailPartials</code> соответственно.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailTemplates</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token comment">// ...Templates defined here</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailLayouts</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token comment">// ...Layouts defined here</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailPartials</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token comment">// ...Partials defined here</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>В панели управления, когда сгенерированный шаблон сохраняется впервые, настроенное содержимое будет использоваться при отправке почты для назначенного кода. В этом контексте зарегистрированные почтовые представления могут рассматриваться как представления по умолчанию или запасные.</p><h4 id="регистрация-шаблона"><a href="#регистрация-шаблона" class="header-anchor">#</a> Регистрация шаблона</h4><p>Ключ <code>templates</code> в массиве регистрации используется для регистрации представлений как почтовых шаблонов. Метод должен возвращать массив, где ключ — код шаблона, а значение — имя <a href="./../services/response-view.html">пути представления</a>. Код шаблона используется для ссылки на шаблон.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailTemplates</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;rainlab.user:activate&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;rainlab.user::mail.activate&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;rainlab.user:restore&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;rainlab.user::mail.restore&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Отправка сообщения использует код шаблона, например.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;rainlab.user:activate&#39;</span><span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="регистрация-макета"><a href="#регистрация-макета" class="header-anchor">#</a> Регистрация макета</h4><p>Переопределение метода <code>registerMailLayouts</code> используется для регистрации макетов, и каждый макет нуждается в уникальном <code>code</code> для идентификации, а также в файле представления по умолчанию для содержимого.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailLayouts</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;marketing&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::layouts.marketing&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;notification&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::layouts.notification&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Макет теперь может быть указан в шаблонах с помощью значения <code>code</code>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">marketing</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code>Page contents...
</code></pre></div></div><h4 id="регистрация-частичного-представления"><a href="#регистрация-частичного-представления" class="header-anchor">#</a> Регистрация частичного представления</h4><p>Как и макеты, почтовые частичные представления могут быть зарегистрированы с помощью переопределения метода <code>registerMailPartials</code>, и каждое частичное представление нуждается в уникальном <code>code</code> для идентификации, а также в файле представления по умолчанию для содержимого.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailPartials</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;tracking&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::partials.tracking&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;promotion&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::partials.promotion&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Частичное представление теперь может быть указано в шаблонах с помощью тега <code>{% partial %}</code> и значения <code>code</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>tracking<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h4 id="фаиловые-макеты"><a href="#фаиловые-макеты" class="header-anchor">#</a> Файловые макеты</h4><p>Для ссылки на файловый макет вы можете передать код представления в свойство <strong>layout</strong>. Например, это почтовое представление ссылается на макет <code>acme.blog::mail.custom-layout</code>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">acme.blog::mail.custom-layout</span>&quot;</span>
<span class="token key attr-name">subject</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Your product has been added to October CMS project</span>&quot;</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div><p>Используя приведённый выше код, система попытается загрузить содержимое макета из пути <strong>plugins/acme/blog/views/mail/custom-layout.htm</strong>, и это содержимое может выглядеть так.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>HTML Contents<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> content<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block warning"><p>Содержимое файловых макетов нельзя редактировать в панели администратора.</p></div><h3 id="глобальные-переменные"><a href="#глобальные-переменные" class="header-anchor">#</a> Глобальные переменные</h3><p>Вы можете регистрировать переменные, глобально доступные для всех почтовых шаблонов, с помощью метода <code>View::share</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">share</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;site_name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;October CMS&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Этот код может быть вызван внутри метода register или boot <a href="./../plugin/registration.html">файла регистрации плагина</a>. В приведённом выше примере переменная <code>{{ site_name }}</code> будет доступна во всех почтовых шаблонах.</p><h2 id="отправка-почты"><a href="#отправка-почты" class="header-anchor">#</a> Отправка почты</h2><p>Для отправки сообщения используйте метод <code>send</code> фасада <code>Mail</code>, который принимает три аргумента. Первый аргумент — уникальный почтовый код, используемый для поиска почтового представления или почтового шаблона. Второй аргумент — массив данных, которые вы хотите передать в представление. Третий аргумент — обратный вызов <code>Closure</code>, получающий экземпляр сообщения, позволяя вам настраивать получателей, тему и другие аспекты почтового сообщения.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// These variables are available inside the message as Twig</span>
<span class="token variable">$vars</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Joe&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;user&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Mary&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog:message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$vars</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;admin@domain.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Admin Person&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">subject</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;This is a reminder&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Поскольку мы передаём массив, содержащий ключ <code>name</code>, в приведённом выше примере, мы можем отобразить значение в нашем представлении электронного письма с помощью следующей Twig-разметки.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><div class="custom-block warning"><p>Избегайте передачи переменной <code>message</code> в ваше сообщение — эта переменная всегда передаётся и позволяет встраивать вложения.</p></div><h3 id="быстрая-отправка"><a href="#быстрая-отправка" class="header-anchor">#</a> Быстрая отправка</h3><p>October CMS также включает альтернативный метод <code>sendTo</code>, который может упростить отправку почты.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Send to address using no name</span>
<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;admin@domain.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Send using an object&#39;s properties</span>
<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Send to multiple addresses</span>
<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;admin@domain.tld&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Admin Person&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Alternatively send a raw message without parameters</span>
<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">rawTo</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;admin@domain.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Hello friend&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Первый аргумент в <code>sendTo</code> используется для получателей и может принимать различные типы значений.</p><div class="table"><table tabindex="0"><thead><tr><th>Тип</th><th>Описание</th></tr></thead><tbody><tr><td>String</td><td>один адрес получателя без указания имени.</td></tr><tr><td>Array</td><td>несколько получателей, где ключ массива — адрес, а значение — имя.</td></tr><tr><td>Object</td><td>один объект получателя, где свойство <em>email</em> используется для адреса, а <em>name</em> — опционально для имени.</td></tr><tr><td>Collection</td><td>коллекция объектов получателей, как описано выше.</td></tr></tbody></table></div><p>Полная сигнатура <code>sendTo</code> выглядит следующим образом.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token variable">$recipient</span><span class="token punctuation">,</span> <span class="token variable">$message</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">,</span> <span class="token variable">$callback</span><span class="token punctuation">,</span> <span class="token variable">$options</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><ul><li><code>$recipient</code> определён как описано выше.</li><li><code>$message</code> — имя шаблона или содержимое сообщения для отправки в сыром виде.</li><li><code>$params</code> — массив переменных, доступных внутри шаблона.</li><li><code>$callback</code> вызывается с одним параметром — построителем сообщения, как описано для метода <code>send</code> (необязательно, по умолчанию null). Если значение не является вызываемым, работает как замена следующего аргумента options.</li><li><code>$options</code> — пользовательские параметры отправки, передаваемые как массив (необязательно).</li></ul><p>Поддерживаются следующие пользовательские <code>$options</code> отправки.</p><div class="table"><table tabindex="0"><thead><tr><th>Параметр</th><th>Описание</th></tr></thead><tbody><tr><td><strong>queue</strong></td><td>определяет, ставить ли сообщение в очередь или отправлять напрямую, необязательно. По умолчанию: <code>false</code>.</td></tr><tr><td><strong>bcc</strong></td><td>определяет, добавлять ли получателей как Bcc или обычные To адреса. По умолчанию: <code>false</code>.</td></tr></tbody></table></div><h3 id="построение-сообщения"><a href="#построение-сообщения" class="header-anchor">#</a> Построение сообщения</h3><p>Как упоминалось ранее, третий аргумент метода <code>send</code> — это <code>Closure</code>, позволяющее указать различные параметры самого почтового сообщения. С помощью этого замыкания вы можете указать другие атрибуты сообщения, такие как копии, скрытые копии и т.д.:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$vars</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">from</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;us@example.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;October&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo@example.tld&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">cc</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;bar@example.tld&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вот список доступных методов экземпляра построителя сообщений <code>$message</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">from</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">sender</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">cc</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">bcc</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">replyTo</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">subject</span><span class="token punctuation">(</span><span class="token variable">$subject</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">priority</span><span class="token punctuation">(</span><span class="token variable">$level</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">attach</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">,</span> <span class="token keyword type-hint">array</span> <span class="token variable">$options</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Attach a file from a raw $data string...</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">attachData</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token keyword type-hint">array</span> <span class="token variable">$options</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="отправка-простого-текста"><a href="#отправка-простого-текста" class="header-anchor">#</a> Отправка простого текста</h4><p>По умолчанию представление, переданное методу <code>send</code>, считается содержащим почтовое представление, где вы можете указать представление простого текста для отправки в дополнение к HTML-представлению.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog:message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token variable">$callback</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Или, если вам нужно отправить только текстовое электронное письмо, вы можете указать это с помощью ключа <code>text</code> в массиве:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;text&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog:text&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token variable">$callback</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="отправка-обработанных-сырых-строк"><a href="#отправка-обработанных-сырых-строк" class="header-anchor">#</a> Отправка обработанных сырых строк</h4><p>Вы можете использовать метод <code>raw</code>, если хотите отправить сырую строку напрямую. Это содержимое будет обработано Markdown.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Text to e-mail&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Кроме того, эта строка будет обработана Twig. Если вы хотите передать переменные в эту среду, используйте метод <code>send</code>, передав содержимое как ключ <code>raw</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;raw&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Text to email&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token variable">$vars</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="отправка-сырых-строк"><a href="#отправка-сырых-строк" class="header-anchor">#</a> Отправка сырых строк</h4><p>Если вы передаёте массив, содержащий ключи <code>text</code> или <code>html</code>, это будет явный запрос на отправку почты. Макет и обработка Markdown не используются.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;text&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is plain text&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;html&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;&lt;strong&gt;This is HTML&lt;/strong&gt;&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="отправка-вложении"><a href="#отправка-вложении" class="header-anchor">#</a> Отправка вложений</h3><p>Для добавления вложений к электронному письму используйте метод <code>attach</code> объекта <code>$message</code>, переданного в ваше замыкание. Метод <code>attach</code> принимает полный путь к файлу в качестве первого аргумента:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>

    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">attach</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>При прикреплении файлов к сообщению вы также можете указать отображаемое имя и/или MIME-тип, передав <code>array</code> вторым аргументом метода <code>attach</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">attach</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;as&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$display</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;mime&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$mime</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="встроенные-вложения"><a href="#встроенные-вложения" class="header-anchor">#</a> Встроенные вложения</h3><h4 id="встраивание-изображения-в-содержимое-письма"><a href="#встраивание-изображения-в-содержимое-письма" class="header-anchor">#</a> Встраивание изображения в содержимое письма</h4><p>Встраивание встроенных изображений в электронные письма обычно затруднительно, однако существует удобный способ прикрепления изображений и получения соответствующего CID. Для встраивания встроенного изображения используйте метод <code>embed</code> переменной <code>message</code> в вашем представлении письма. Помните, переменная <code>message</code> доступна во всех ваших почтовых представлениях:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    Here is an image:

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message<span class="token punctuation">.</span>embed<span class="token punctuation">(</span>pathToFile<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Если вы планируете использовать очереди для отправки писем, убедитесь, что путь к файлу является абсолютным. Для этого можно просто использовать <a href="./../../markup/filter/app.html">фильтр app</a>:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    Here is an image:
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> pathToFile <span class="token operator">=</span> <span class="token string"><span class="token punctuation">&#39;</span>storage/app/media/path/to/file.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>app <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message<span class="token punctuation">.</span>embed<span class="token punctuation">(</span>pathToFile<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h4 id="встраивание-сырых-данных-в-содержимое-письма"><a href="#встраивание-сырых-данных-в-содержимое-письма" class="header-anchor">#</a> Встраивание сырых данных в содержимое письма</h4><p>Если у вас уже есть строка сырых данных, которую вы хотите встроить в почтовое сообщение, вы можете использовать метод <code>embedData</code> переменной <code>message</code>:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    Here is an image from raw data:

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message<span class="token punctuation">.</span>embedData<span class="token punctuation">(</span>data<span class="token punctuation">,</span> name<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="очередь-почты"><a href="#очередь-почты" class="header-anchor">#</a> Очередь почты</h2><h3 id="постановка-почтового-сообщения-в-очередь"><a href="#постановка-почтового-сообщения-в-очередь" class="header-anchor">#</a> Постановка почтового сообщения в очередь</h3><p>Поскольку отправка почтовых сообщений может значительно увеличить время ответа вашего приложения, многие разработчики предпочитают ставить сообщения в очередь для фоновой отправки. Это легко сделать с помощью встроенного <a href="./../services/queue.html">унифицированного API очередей</a>. Для постановки почтового сообщения в очередь используйте метод <code>queue</code> фасада <code>Mail</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">queue</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Этот метод автоматически добавит задачу в очередь для отправки почтового сообщения в фоновом режиме. Конечно, перед использованием этой функции необходимо <a href="./../services/queue.html">настроить очереди</a>.</p><h3 id="отложенная-постановка-в-очередь"><a href="#отложенная-постановка-в-очередь" class="header-anchor">#</a> Отложенная постановка в очередь</h3><p>Если вы хотите задержать доставку поставленного в очередь электронного письма, используйте метод <code>later</code>. Для начала просто передайте количество секунд задержки отправки сообщения первым аргументом метода.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">later</span><span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="отправка-в-конкретные-очереди"><a href="#отправка-в-конкретные-очереди" class="header-anchor">#</a> Отправка в конкретные очереди</h3><p>Если вы хотите указать конкретную очередь для отправки сообщения, используйте методы <code>queueOn</code> и <code>laterOn</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">queueOn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;queue-name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">laterOn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;queue-name&#39;</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../setup/mail-config.html">Настройка почты</a></li></ul></div>`,114))])}const f=e(u,[["render",r]]);export{b as __pageData,f as default};
